export function playSoundsBang()       {
    {
        let head      = wasm.sp_snd_head();
        let base      = wasm.sp_snd_addr();
        if (((head - sndSeen) > 64)) {
            sndSeen = (head - 64);
        }
        {
            let i         = sndSeen;
            while (true) {
                if ((i < head)) {
                    if (audioReadyP()) {
                        {
                            let a      = (base + ((i & 63) * 16));
                            playSoundBang(view.getInt32(a, true), view.getFloat32((a + 4), true), view.getFloat32((a + 8), true), view.getFloat32((a + 12), true));
                        }
                    }
                    i = (i + 1);
                    continue;
                }
                break;
            }
        }
        sndSeen = head;
    }
}

